    target.innerHTML = formatter.format(dt)
    target.title = this.datetimeFormatter.format(dt)
  }
}

class AgoFormatter {
  format(dt) {
    const now = new Date()
    const seconds = (now - dt) / 1000
    const minutes = seconds / 60
    const hours = minutes / 60
    const days = hours / 24
    const weeks = days / 7
    const months = days / (365 / 12)
    const years = days / 365

    if (years >= 1) return this.#format("year", years)
    if (months >= 1) return this.#format("month", months)
    if (weeks >= 1) return this.#format("week", weeks)
    if (days >= 1) return this.#format("day", days)
    if (hours >= 1) return this.#format("hour", hours)
    if (minutes >= 1) return this.#format("minute", minutes)

    return t("less_than_a_minute_ago", "Less than a minute ago")
  }

  #format(unit, quantity) {
    quantity = Math.floor(quantity)
    const label = quantity === 1 ? t(unit, unit) : t(`${unit}s`, `${unit}s`)
    return t("ago_format", `${quantity} ${label} ago`, { count: quantity, unit: label })
  }
}

class DaysAgoFormatter {
  format(date) {
    const days = differenceInDays(date, new Date())

    if (days <= 0) return styleableValue(t("today", "today"))
    if (days === 1) return styleableValue(t("yesterday", "yesterday"))
    return styleableValue(t("days_ago_format", `${days} days ago`, { count: days }))
  }
}

class DaysAgoOrWeekdayFormatter {
  format(date) {
    const days = differenceInDays(date, new Date())

    if (days <= 1) {
      return new DaysAgoFormatter().format(date)
    } else {
      return new Intl.DateTimeFormat(dateLocale(), { weekday: "long", month: "long", day: "numeric" }).format(date)
    }
  }
}

class InDaysFormatter {
  format(date) {
    const days = differenceInDays(new Date(), date)

    if (days <= 0) return styleableValue(t("today", "today"))
    if (days === 1) return styleableValue(t("tomorrow", "tomorrow"))
    return styleableValue(t("in_days_format", `in ${days} days`, { count: days }))
  }
}

class TimeOrDateFormatter {
  format(date) {
    const days = differenceInDays(date, new Date())

    if (days >= 1) {
      return new Intl.DateTimeFormat(dateLocale(), { month: "short", day: "numeric" }).format(date)
    } else {
      return new Intl.DateTimeFormat(dateLocale(), { timeStyle: "short" }).format(date)
    }
  }
}

function styleableValue(value) {
  return `<span class="local-time-value">${value}</span>`
}
